// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Gap report: compare newest site map with job catalog
// Flo: newest <stat>/map/<date>/ > per job: first button or box name on its page (missing = UI drift) > controls no label knows (new things to automate) > counts, lists, exit 3 on drift ; matrix = every job with area, class, cap, page
// I/O: map files + catalog + config (caller) > text or JSON lines; error Drift when a job's first name is not on its mapped page; BadUsage when no map exists yet
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const jobs = @import("ru-jobs-tabl.zig"); const jrun = @import("ru-jobs-main.zig"); const crwl = @import("ru-map-crwl.zig"); const pack = @import("ut-loca-pack.zig"); const fld = @import("ut-text-fold.zig"); const disp = @import("ru-jobs-disp.zig");
const CF = .{ .maxf = 1 << 20, .maxu = 200, .idx = "index.json" };
pub const Rep = struct { pages: usize, unmapped: u32, drift: []const []const u8, unused: []const []const u8 };
fn dirsDesc(ctx: *task.Ctx) ![]const []const u8 { const root = try std.fs.path.join(ctx.aren, &.{ ctx.statd, "map" }); var dirz = std.Io.Dir.cwd().openDir(ctx.iozz, root, .{ .iterate = true }) catch return &.{}; defer dirz.close(ctx.iozz); var names: std.ArrayList([]const u8) = .empty; var itr = dirz.iterate(); while (try itr.next(ctx.iozz)) |ite| { if (ite.kind == .directory) try names.append(ctx.aren, try ctx.aren.dupe(u8, ite.name)); } std.mem.sort([]const u8, names.items, {}, struct { fn gt(_: void, aa: []const u8, bb: []const u8) bool { return std.mem.order(u8, aa, bb) == .gt; } }.gt); var out: std.ArrayList([]const u8) = .empty; for (names.items) |nm| try out.append(ctx.aren, try std.fs.path.join(ctx.aren, &.{ root, nm })); return out.items; }
pub fn loadDir(ctx: *task.Ctx, dir: []const u8) ![]const crwl.PageMap { var dirz = try std.Io.Dir.cwd().openDir(ctx.iozz, dir, .{ .iterate = true }); defer dirz.close(ctx.iozz); var out: std.ArrayList(crwl.PageMap) = .empty; var itr = dirz.iterate(); while (try itr.next(ctx.iozz)) |ite| { if (ite.kind != .file or !std.mem.endsWith(u8, ite.name, ".json") or std.mem.eql(u8, ite.name, CF.idx)) continue; const fp = try std.fs.path.join(ctx.aren, &.{ dir, ite.name }); const byte = std.Io.Dir.cwd().readFileAlloc(ctx.iozz, fp, ctx.aren, .limited(CF.maxf)) catch continue; const pm = std.json.parseFromSliceLeaky(crwl.PageMap, ctx.aren, byte, .{ .ignore_unknown_fields = true, .allocate = .alloc_always }) catch continue; try out.append(ctx.aren, pm); } return out.items; }
fn pathPart(urlz: []const u8) []const u8 { if (std.mem.startsWith(u8, urlz, "http")) { const sch = std.mem.find(u8, urlz, "://") orelse return urlz; const rest = urlz[sch + 3 ..]; const sl = std.mem.findScalar(u8, rest, '/') orelse return "/"; return rest[sl..]; } return urlz; }
fn pageFor(pages: []const crwl.PageMap, path: []const u8) ?crwl.PageMap { for (pages) |pg| { if (std.mem.eql(u8, pg.path, path)) return pg; } return null; }
fn firstLab(job: *const jobs.Job) ?jobs.T { for (job.steps) |tpl| { if (tpl.key.len == 0) continue; switch (tpl.op) { .click, .typez, .select, .toggle, .confirm, .hover => return tpl, else => {} } } return null; }
fn joined(ctx: *task.Ctx, pg: crwl.PageMap) ![]const u8 { var out: std.ArrayList(u8) = .empty; for (pg.ctl) |cl| { try out.appendSlice(ctx.aren, cl.n); try out.append(ctx.aren, '\n'); } return out.items; }
pub fn compute(ctx: *task.Ctx, dir: []const u8) !Rep { const pages = try loadDir(ctx, dir); var drift: std.ArrayList([]const u8) = .empty; var unmapped: u32 = 0;
for (&jobs.JOBS) |*jb| { if (jb.src == .url or jb.src == .dmsg_thre or jb.steps[0].soft) continue; const tpl = firstLab(jb) orelse continue; const path = pathPart(jrun.pathOf(ctx, .{}, jb.src, jb.pkey) catch continue); const pg = pageFor(pages, path) orelse { unmapped += 1; continue; }; const labs = pack.lab(ctx.conf, tpl.key); if (labs.len == 0) continue; if (!(try fld.matchAny(ctx.aren, try joined(ctx, pg), labs))) try drift.append(ctx.aren, try std.fmt.allocPrint(ctx.aren, "{s}: \"{s}\" not on {s}", .{ jb.name, labs[0], path })); }
const known = try pack.allLabs(ctx.aren, ctx.conf); var folded: std.ArrayList([]const u8) = .empty; for (known) |lb| try folded.append(ctx.aren, try fld.foldAlloc(ctx.aren, lb)); var unused: std.ArrayList([]const u8) = .empty;
for (pages) |pg| { for (pg.ctl) |cl| { if (unused.items.len >= CF.maxu) break; const fn_ = try fld.foldAlloc(ctx.aren, cl.n); var hit = false; for (folded.items) |kn| { if (std.mem.eql(u8, kn, fn_)) { hit = true; break; } } if (!hit) try unused.append(ctx.aren, try std.fmt.allocPrint(ctx.aren, "{s} | {s} | {s}", .{ pg.path, cl.r, cl.n })); } }
return .{ .pages = pages.len, .unmapped = unmapped, .drift = drift.items, .unused = unused.items }; }
pub fn gapsRun(ctx: *task.Ctx, sub: []const u8, json: bool) !void { if (std.mem.eql(u8, sub, "matrix")) return matrix(ctx, json); const dirs = try dirsDesc(ctx); if (dirs.len == 0) { task.say(ctx, "no site map yet: run fb-face-webs map first", .{}); return error.BadUsage; } const rep = try compute(ctx, dirs[0]);
if (json) { task.say(ctx, "{s}", .{try std.json.Stringify.valueAlloc(ctx.aren, rep, .{})}); } else { task.say(ctx, "gaps: {d} pages mapped, {d} jobs on unmapped pages, {d} drift, {d} controls no label knows", .{ rep.pages, rep.unmapped, rep.drift.len, rep.unused.len }); for (rep.drift) |ln| task.say(ctx, "DRIFT {s}", .{ln}); for (rep.unused) |ln| task.say(ctx, "NEW   {s}", .{ln}); }
if (rep.drift.len > 0) return error.Drift; }
pub fn matrix(ctx: *task.Ctx, json: bool) !void { _ = json; var ix: usize = 0; while (ix < disp.rowCount()) : (ix += 1) { const rw = disp.rowAt(ix); const jb = jobs.find(rw.name); const where = if (jb) |hit| (if (hit.pkey.len > 0) hit.pkey else @tagName(hit.src)) else "code"; task.say(ctx, "{s} | {s} | {c} | {s} | {s}", .{ rw.name, rw.area, rw.cls, rw.kind, where }); } }
